class Solution:
    def findRadius(self, houses: list[int], heaters: list[int]) -> int:
        houses.sort()
        heaters.sort()
        radius, index = 0, 0
        for house in houses:
            while index + 1 < len(heaters) and house - heaters[index] > heaters[index + 1] - house:
                index += 1
            radius = max(radius, abs(house - heaters[index]))
        return radius

